                                      "quote": "제1조(보험금의 지급사유)\n회사는 피보험자가 이 특약의 보험기간 중 별표 [성인주요질환 분류표]에 정한 질환으로 진단확정되고 그 질환의 직접적인 치료를 목적으로 수술을 받은 때에는 군별 성인병 수술급여금을 지급합니다.\n\n제2조(질환군별 지급 기준)\n1. 3대 주요질환: 악성신생물(암 C00~C97), 뇌혈관질환(I60~I69), 허혈심장질환(I20~I25) ➔ 1회당 최고 가입금액 전액 지급\n2. 7대 성인병: 고혈압, 당뇨병, 만성 간질환, 만성 하기도질환, 만성 신부전 등 ➔ 약정 정액 급여금 지급\n3. 11대/14대 성인병: 위십이지장궤양, 담석증, 결핵, 패혈증, 갑상선질환, 녹내장 등 ➔ 약정 정액 급여금 지급\n\n제3조(타 수술특약과의 중복 합산 지급)\n이 특약에 의한 성인병 수술급여금은 질병수술특약 및 1~5종 수술특약의 지급 여부와 관계없이 별도의 독립된 보장으로 중복하여 합산 지급합니다.\n\n제4조(비관혈 수술 감액 조항 배제)\n생명보험 성인주요질환 특약은 손해보험 N대 질병수술비와 달리 내시경, 복강경 등 비관혈 수술에 대한 50% 감액 조항이 없어 가입금액 100% 전액을 지급합니다.",
