                                      "quote": "제1조(보험금의 지급사유)\n피보험자가 보험기간 중 질병 또는 재해로 인하여 병원 또는 의원 등에 입원 또는 통원하여 별표 [1~5종 수술분류표]에 정한 수술을 받았을 때에는 각 수술의 종류에 따라 종별 수술급여금을 지급합니다.\n\n제2조(수술의 종별 구분)\n수술분류표에 정한 수술 항목 번호에 따라 해당 등급의 정액 급여금을 차등 지급합니다.\n\n제3조(동시수술 및 다른 부위 수술 규정 - 신체부위 분리형)\n① 하나의 질병으로 인한 수술이 아니거나 각각 다른 신체부위에 대하여 수술을 받은 때에는 각각의 수술비를 지급합니다.\n② 동일 질병 치료 목적으로 2회 이상 수술 시 원칙적으로 1회 지급을 적용합니다.",
