                                      "quote": "제1조(보험금의 지급사유)\n피보험자가 보험기간 중 질병 또는 재해로 인하여 병원 또는 의원 등에 입원 또는 통원하여 별표 [1~5종 수술분류표]에 정한 수술을 받았을 때에는 각 수술의 종류에 따라 종별 수술급여금을 지급합니다.\n\n제2조(수술의 종별 구분)\n수술분류표에 정한 수술 항목 번호에 따라 해당 등급의 정액 급여금을 차등 지급합니다.\n\n제3조(동일 신체부위 동시수술 제한 규정 - C타입 복부체강 동일부위제한)\n① 동시에 두 가지 이상의 수술을 받은 경우로서 각각 다른 신체부위에 대하여 수술을 받은 때에는 각각의 수술에 해당하는 급여금을 지급합니다.\n② 단, '동일한 신체부위'라 함은 각각 독립된 장기라도 복부, 흉부, 골반강 등 동일한 체강(體腔) 내에 위치한 장기(예: 위 절제술과 대장 절제술을 동시 시행한 경우)는 동일한 부위로 간주하여 그 중 가장 높은 1개 수술급여금만 지급합니다.\n③ 좌우 대칭 기관(눈, 귀, 팔, 다리 등)은 각각 독립된 다른 신체부위로 인정하여 양측 동시 수술 시 각각 지급합니다.",
